    '.sp-ico svg{width:18px;height:18px}',
    '.sp-ico:hover{color:var(--sp-gold);background:var(--sp-glow)}',
    '.sp-ico.on{color:var(--sp-gold)}',
    '.sp-screen{flex:1;min-height:0;display:flex;flex-direction:column;position:relative}',
    '.sp-body{flex:1;min-height:0;overflow-y:auto;overscroll-behavior:contain}',
    '.sp-home{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:28px;position:relative;',
    'background:radial-gradient(125% 85% at 50% -12%,#1c2540 0%,#0f1424 46%,#080b14 100%)}',
    '.sp-home::before{content:"";position:absolute;inset:0;pointer-events:none;opacity:.35;',
    'background:repeating-linear-gradient(0deg,transparent 0 46px,rgba(127,212,232,.05) 46px 47px)',
    'repeating-linear-gradient(90deg,transparent 0 46px,rgba(127,212,232,.05) 46px 47px)}',
    '.sp-lock{text-align:center;position:relative;z-index:1}',
    '.sp-lock .h{font-size:50px;font-weight:300;letter-spacing:3px;font-variant-numeric:tabular-nums;',
    'color:#f4f7fc;text-shadow:0 0 34px rgba(232,213,168,.22),0 2px 12px rgba(0,0,0,.65);line-height:1}',
    '.sp-lock .d{font-size:12px;color:var(--sp-dim);letter-spacing:2.6px;margin-top:9px}',
    '.sp-lock .era{font-size:9.5px;color:var(--sp-gold2);letter-spacing:3px;margin-top:5px;opacity:.85}',
    /* 设置页里那种"勾选框 + 文字"的一行：文字必须能换行，不能竖排 */
    '.sp-check{display:flex;align-items:center;gap:8px;margin-top:9px;min-width:0}',
    '.sp-check input[type=checkbox]{flex:0 0 auto;width:16px;height:16px;accent-color:#e8d5a8;margin:0}',
    '.sp-check label{flex:1 1 auto;min-width:0;font-size:12.5px;line-height:1.5;color:var(--sp-text);letter-spacing:0;word-break:break-word}',
    /* 群成员行：头像 + 名字，可点 */
    '.sp-mrow{display:flex;align-items:center;gap:9px;padding:7px 9px;background:rgba(255,255,255,.028);border:1px solid var(--sp-line2);border-radius:3px;cursor:pointer;transition:background .15s}',
    '.sp-mrow:hover{background:rgba(127,212,232,.09);border-color:rgba(127,212,232,.35)}',
    '.sp-mrow.me{background:rgba(232,213,168,.07);border-color:rgba(232,213,168,.28);cursor:default}',
    '.sp-mrow .sp-main{flex:1;min-width:0}',
    '.sp-tag.me{background:rgba(232,213,168,.16);color:var(--sp-gold)}',
    '.sp-tag.invite{background:rgba(127,212,232,.16);color:var(--sp-cyan)}',
    '.sp-ico.ok{color:#8fe0a8}',
    /* 群聊邀请卡 */
    '.sp-row.sp-invite{background:linear-gradient(90deg,rgba(127,212,232,.10),rgba(127,212,232,.02));border-left:2px solid var(--sp-cyan)}',
    /* 还没加入的群：聊天页顶上的横幅 */
    '.sp-invbar{margin:10px 0;padding:11px 12px;background:linear-gradient(180deg,rgba(127,212,232,.13),rgba(127,212,232,.05));border:1px solid rgba(127,212,232,.35);border-radius:3px}',
    '.sp-invbar .t{font-size:13px;color:var(--sp-cyan);letter-spacing:.5px}',
    '.sp-invbar .r{font-size:12px;color:var(--sp-dim);margin-top:5px;line-height:1.6}',
    '.sp-invbar .sp-btns{margin-top:9px}',
    '.sp-lock .n{font-size:12px;color:var(--sp-gold);margin-top:16px;min-height:18px;letter-spacing:.5px}',
    '.sp-apps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px 6px;justify-items:center;position:relative;z-index:1}',
    '.sp-app{display:flex;flex-direction:column;align-items:center;gap:8px;position:relative;cursor:pointer}',
    '.sp-app .ic{width:58px;height:58px;display:flex;align-items:center;justify-content:center;position:relative;',
    'background:linear-gradient(160deg,#1e2740,#131a2c);border:1px solid var(--sp-line2);color:var(--sp-gold);',
    'clip-path:polygon(13px 0,100% 0,100% calc(100% - 13px),calc(100% - 13px) 100%,0 100%,0 13px);',
    'box-shadow:inset 0 1px 0 rgba(255,255,255,.07);transition:.18s}',
