    '.sp-app .lb{font-size:11.5px;color:var(--sp-dim);letter-spacing:1.6px}',
    '.sp-app .bd{position:absolute;top:-7px;right:-5px;min-width:20px;height:20px;border-radius:10px;z-index:2;',
    'background:linear-gradient(180deg,#e05a5a,#c0392b);color:#fff;font-size:11px;line-height:20px;text-align:center;',
    'padding:0 5px;font-weight:700;box-shadow:0 0 0 2px #0c1120,0 3px 9px rgba(0,0,0,.5);font-family:system-ui,sans-serif}',
    '.sp-app .bd.pulse{animation:sp-pulse 1.8s ease-in-out infinite}',
    '@keyframes sp-pulse{0%,100%{transform:scale(1)}50%{transform:scale(1.13)}}',
    '.sp-foot{font-size:10.5px;color:var(--sp-dim2);letter-spacing:1.8px;position:relative;z-index:1}',
    '.sp-row{display:flex;align-items:center;gap:12px;padding:12px 15px;cursor:pointer;transition:.13s;',
    'border-bottom:1px solid rgba(35,44,70,.55);position:relative;border-left:2px solid transparent}',
    '.sp-row:hover{background:linear-gradient(90deg,rgba(232,213,168,.07),transparent 72%);border-left-color:var(--sp-gold2)}',
    '.sp-row:active{background:rgba(232,213,168,.05)}',
    '.sp-av{width:44px;height:44px;flex:0 0 auto;display:flex;align-items:center;justify-content:center;',
    'font-size:17px;font-weight:600;color:#fff;position:relative;',
    'clip-path:polygon(9px 0,100% 0,100% calc(100% - 9px),calc(100% - 9px) 100%,0 100%,0 9px);',
    'box-shadow:inset 0 1px 0 rgba(255,255,255,.18),inset 0 -8px 14px rgba(0,0,0,.28);text-shadow:0 1px 3px rgba(0,0,0,.55)}',
    '.sp-av.sm{width:34px;height:34px;font-size:13.5px;clip-path:polygon(7px 0,100% 0,100% calc(100% - 7px),calc(100% - 7px) 100%,0 100%,0 7px)}',
    '.sp-av.xs{width:27px;height:27px;font-size:12px;clip-path:polygon(6px 0,100% 0,100% calc(100% - 6px),calc(100% - 6px) 100%,0 100%,0 6px)}',
    '.sp-av.group{clip-path:none;border-radius:4px}',
    '.sp-main{flex:1;min-width:0}',
    '.sp-l1{display:flex;align-items:baseline;gap:7px}',
    '.sp-name{font-size:14px;font-weight:600;letter-spacing:.9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}',
    '.sp-split{opacity:.75;letter-spacing:1px}',
    '.sp-locked{display:block;padding:12px 14px}',
