    '.sp-tag{font-size:10px;padding:1px 7px;border:1px solid var(--sp-line2);color:var(--sp-dim);flex:0 0 auto;',
    'letter-spacing:.8px;clip-path:polygon(4px 0,100% 0,100% calc(100% - 4px),calc(100% - 4px) 100%,0 100%,0 4px)}',
    '.sp-tag.pend{background:rgba(232,213,168,.12);border-color:var(--sp-gold2);color:var(--sp-gold)}',
    '.sp-tag.left{background:rgba(224,138,138,.1);border-color:#5c3a3a;color:#c99}',
    '.sp-unread{min-width:20px;height:20px;background:linear-gradient(180deg,#e05a5a,#c0392b);color:#fff;font-size:11px;',
