      if (!sid) return;
      if (!core.isRenderableSession(state(), sid)) return;
      if (!hooks.onSend) return;
      var imgs = draftOf(sid).images.slice();
      if (!text && !imgs.length) return;      /* 空的不发 */
      if (ta) { ta.value = ''; autoGrow(ta); }
