    kbRecall: kbTestRecall,
    kbRecallDepth: KB_RECALL_DEPTH,   /* 记忆块写进第几层（2 = 倒数第三层） */
    kbPending: kbPending,             /* 还有几层没总结（只数有正文的楼层） */
    kbFirstPending: kbFirstPending,   /* 第一层还没总结的楼层号（没有 = -1） */
    kbCoverage: kbCoverage,           /* 已总结覆盖的楼层区间 */
    kbLastFloor: kbLastFloor,
    kbSync: kbSyncSoon,
    kbStats: kbWorldbookStats,
