    kb.summaries.sort(function (a, b) { return a.no - b.no; });
    var maxNo = 0;
    kb.summaries.forEach(function (s) { if (s.no > maxNo) maxNo = s.no; });
    kb.nextNo = Math.max(Number(d.nextNo) || 1, maxNo + 1);

