    'transform:translateZ(0);',
    'box-shadow:inset 0 0 0 1px rgba(255,255,255,.22)}',
    '.kcone-front img{position:absolute;inset:2px;width:calc(100% - 4px);height:calc(100% - 4px);',
    'object-fit:cover;display:block;border-radius:12px;',
    'user-select:none;-webkit-user-drag:none}',
    /* 背面：半透明的画色，从侧边看过去像磨砂 */
    '.kcone-back{position:absolute;inset:0;opacity:.55;backface-visibility:hidden;',
